#!/usr/bin/env bash
# Lab B26 -- Moonshine Tiny's speech ENCODER, code-generated by ModelBlaster and run end to
# end on hart 0: the measured software baseline an accelerator is compared against.
#
#   ./scripts/50_rocket_moonshine_enc.sh --build-only                         # 1. no board
#   scripts/with_board.sh ./scripts/50_rocket_moonshine_enc.sh --board-only   # 2. board only
#
# Two steps so the board lock is never held across a build (codegen, host gates, the
# fidelity check and a dozen Zephyr images); --board-only reuses out/<name>/ as step 1 left
# it, --report-only re-parses what the board step collected.
#
# WHAT RUNS.  UsefulSensors/moonshine-tiny @ 390624ed, the encoder only, 4.0 s of 16 kHz
# speech (64,000 samples -> 165 frames), int8 through ModelBlaster's FX path with
# patches/0100 (tanh_s8, groupnorm_s8, rope_s8, multi-head attention as matmul_b_s8,
# view/permute).  The port is fpga/pynq-z2/modelblaster/moonshine/moonshine_enc.py and is
# bit-identical to transformers' MoonshineEncoder in float32.
#
# SOFTWARE BASELINES (--variants), one IR, same silicon, same session:
#   nl       pext_nl AS REGISTERED before patches/0100's kernels: MBP conv/linear, integer
#            GELU / layer norm / softmax, and the ops 0100 adds to the IR at their float
#            REFERENCE -- tanh_s8, groupnorm_s8, rope_s8 and add_s8 pinned with
#            --keep-reference-ops.  (matmul_b_s8 is not elementwise and takes its curated
#            DOT8 kernel in both.)
#   ew       plus the integer / memo elementwise kernels: tanh memo table (bit-exact), integer
#            add and rope (bit-exact, fpga/pynq-z2/sw/fexact32.h), integer group norm (1 LSB).
#   nl_eng   nl and ew with ModelBlaster target `roccmoon` (patches/0102): linear_s8 and the
#   ew_eng   1-D stem conv2d_s8 on the decoupled RoCC engine of bitstream 0x5A5A0010.  Same
#            IR (checked); the host-C golden must be BYTE-IDENTICAL to the twin's (checked:
#            on the host the engine kernels are the curated MBP fallback).  Run them with
#            --bit/--magic/--board/--runner for that bitstream and ROCCMOON_ACCEPTED=<md5>.
#   *_smx    any of the above with softmax_s8 taken by `pext_int_memo` (patches/0104): the same
#            kernel as pext_int_row with its exponential memoised, BIT-EXACT, so the host-C
#            golden must be byte-identical to the twin without _smx (checked).  One lever,
#            measured on its own (ROCC_DECOUPLED.md 8.14, T1).  Selected by generating from a
#            copy of the curated tree without pext_int_row's file: the reference backend's
#            curated probe walks spec.algorithms in order and does not apply --algorithms.
#   *_smx2   as _smx with `pext_int_memo2` (patches/0106): the memo's multiplies priced for the
#            big core's iterative multiplier, and a per-row zero cutoff.  Bit-exact the same way.
#   *_nhwc   (after _smx/_smx2 if both) the IR rewritten by pipeline/assign_layouts.py with
#            moonshine/layout_hints_moonshine.json: the stem (conv1, tanh, GroupNorm, conv2, GELU,
#            conv3, GELU) becomes an NHWC island (patches/0105), so the engine's convolutions
#            neither gather nor transpose.  Its host-C golden must be byte-identical to the twin
#            without _nhwc (checked here, not by check_moonshine.py, whose per-dispatch gates
#            read the NCHW IR).  T1 lever 2 (ROCC_DECOUPLED.md 8.14).
# ROCC_DECOUPLED.md 7.3 priced nl and nl+ew; this lab replaces the estimates.
#
# THE CONV KERNEL'S BUFFER LIMITS (images *_bigconv, on by default; --no-bigconv).
# pext_patch_dot8 takes its DOT8 path only when IC*KH <= MB_PEXT_CONV_MAXROWS (512) and
# processes output channels in blocks that fit MB_PEXT_CONV_WBYTES (8 KB) of repacked
# weights, re-gathering the patch per block.  Sized for LeNet and DroNet: Moonshine's conv3
# (IC*KH = 576) silently runs the scalar reference (kernel_picks.json still says
# pext_patch_dot8) and conv2 re-gathers every 4 output channels.  enc_ew_bigconv and
# stem_{w,h}_bigconv are the SAME generated C built with -DMB_PEXT_CONV_MAXROWS=2048
# -DMB_PEXT_CONV_WBYTES=2097152: the kernel's own compile-time knobs, same bit-exact answer.
#
# THE LAYOUT LEVER ON MOONSHINE'S OWN STEM (--stems): conv1..conv3 + tanh + GroupNorm + GELU
# alone, time on W ((1, k) kernels over [N,C,1,T], what the encoder uses) against time on H
# ((k, 1) over [N,C,T,1]).  Same int8 tensors either way.
#
# A CONTROL IMAGE (ctrl_ffn, on by default; --no-control) runs first and last: ModelBlaster's
# ffn_block at pext_nl, the block Lab B19 ran on this board.  A silent board is then
# recognisable as a silent board rather than as a property of the model.  And while every
# image runs, Rocket's RAM is read from the PS (moonshine/peek_ram.py): kernel-init flag, SMP
# hand-shake flags, the harness's `big` struct and the per-dispatch cycle records -- evidence
# that does not depend on the UART (--no-peek skips the RAM reads).
#
# THE GOLDEN.  The Python int8 golden is simulated the way the REFERENCE kernels compute
# (MB_INT8_GOLDEN_C_FLOAT=1) and host gate (a) proves the generated C with reference kernels
# reproduces it at every dispatch.  Every variant contains numeric_drift kernels (patches/
# 0060's integer GELU / layer norm / softmax; ew's integer group norm), so each image is baked
# with ITS OWN host-C golden -- the same generated C compiled for the host against pext.h's
# software model of MBP -- and the board must match that exactly.
#
# CALIBRATION.  16 real speech windows, evenly spaced across the utterances
# (moonshine_enc.speech_split), MB_INT8_GELU_AWARE_RANGES=1 (patches/0100; lossless for the
# GELU consumer).  host_fidelity.py measures what int8 does to transcripts.
#
# Produces out/<name>/{run.json,report.txt,host_gates.json,host_fidelity.json,...}.
. "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib/common.sh"
. "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib/bitstream_id.sh"

NAME="rocket_moonshine_enc"
VARIANTS="nl ew"
STEMS="w h"
TARGET="pext_nl"
NCAL=16
# THE AUDIO WINDOW, in seconds.  ModelBlaster's IR is built for one shape, so a rung of the shape
# ladder (ROCC_DECOUPLED.md s8.15.11) is this lab run again at another window over the same weights.
# The port derives every shape from it (moonshine_enc.py, MOONSHINE_WINDOW_S); 4.0 is what every
# measurement before 2026-09-17 used, and RTF is always computed against THIS window, so a rung's
# RTF is its cycles over its own audio.
WINDOW_S_OPT=4.0
FRAMES=""
ITERS=1
BOARD="chipyard_pynqz1_mic"
BIT="$IISWC_ROOT/fpga/pynq-z2/build_rocket_mic_z1/pynqz1_rocket_mic.bit"
RUNNER="run_rocket_mic.py"
SAMPLE="$IISWC_ROOT/samples/modelblaster_pext"
WANT_MAGIC="0x5A5A0005"
FCLK_CORE=34.4828
LOAD_BIT=1
DO_BOARD=1
HOST_GATES=1
FIDELITY=1
BOARD_ONLY=0
REPORT_ONLY=0
BIGCONV=1
CONTROL=1
ONLY_MODELS=""
RELOAD_PER_MODEL=1
PEEK_RAM=1
MAXREAD_ENC=5400
MAXREAD_SMALL=300
BIGCONV_CFLAGS="-DMB_PEXT_CONV_MAXROWS=2048 -DMB_PEXT_CONV_WBYTES=2097152"
# --kernel-cflags: appended to EVERY image's kernels.c flags (recorded in kernel_cflags.txt).
# For code-placement control (ROCC_DECOUPLED.md 8.15): e.g. -falign-loops=4 puts every loop
# head of the kernel TU -- the engine runtime and mbxr.c included -- on a 4-byte boundary.
KCF_ALL=""
while [ $# -gt 0 ]; do
  case "$1" in
    --name) NAME="${2:?}"; shift 2 ;;
    --variants) VARIANTS="${2:?}"; shift 2 ;;
    --stems) STEMS="${2}"; shift 2 ;;
    --iters) ITERS="${2:?}"; shift 2 ;;
    --board) BOARD="${2:?}"; shift 2 ;;
    --bit) BIT="${2:?}"; shift 2 ;;
    --magic) WANT_MAGIC="${2:?}"; shift 2 ;;
    --runner) RUNNER="${2:?}"; shift 2 ;;
    --no-bitstream) LOAD_BIT=0; shift ;;
    --build-only) DO_BOARD=0; shift ;;
    --board-only) BOARD_ONLY=1; shift ;;
    --report-only) BOARD_ONLY=1; REPORT_ONLY=1; shift ;;
    --models) ONLY_MODELS="${2:?}"; shift 2 ;;
    --no-bigconv) BIGCONV=0; shift ;;
    --kernel-cflags) KCF_ALL="${2}"; shift 2 ;;
    --window-s) WINDOW_S_OPT="${2:?}"; shift 2 ;;
    --no-control) CONTROL=0; shift ;;
    --no-reload) RELOAD_PER_MODEL=0; shift ;;
    --no-peek) PEEK_RAM=0; shift ;;
    --maxread-enc) MAXREAD_ENC="${2:?}"; shift 2 ;;
    --skip-host-gates) HOST_GATES=0; shift ;;
    --skip-fidelity) FIDELITY=0; shift ;;
    -h|--help) sed -n '2,72p' "$0"; exit 0 ;;
    *) die "unknown argument: $1" ;;
  esac
done

# Engine bitstreams are validated by their own lab, not added to lib/bitstream_id.sh's shared
# list (the pattern of scripts/51_rocket_roccmoon.sh and 43_rocket_bwlab.sh).
ROCCMOON_ACCEPTED="${ROCCMOON_ACCEPTED:-}"
BIT_ACCEPTED="${BIT_ACCEPTED:-} $ROCCMOON_ACCEPTED"

MB="$ZCS/modelblaster"
MOON="$IISWC_ROOT/fpga/pynq-z2/modelblaster/moonshine"
KERNELS="$IISWC_ROOT/fpga/pynq-z2/modelblaster/kernels"
[ -d "$MB/pipeline" ] || die "no modelblaster checkout at $MB"
# THE ENGINE'S OUTSTANDING CAP IS A PROPERTY OF THE BITSTREAM'S L2, not of the image.  The driver
# asks for 4 by default (mbxr_rt.h, MBXR_RT_CAP), which is right only where patch 0092 is in the
# L2: Lab B25's sweep reads 7.342 B/cycle at cap 4 on 0x5A5A0028 and DIPS at 4 on the builds
# without it.  So this lab keys the flag off the MAGIC it was told to run against, and an image
# built for one bitstream carries the cap that bitstream wants.  MBXR_CAP=<n> overrides.
case "${MBXR_CAP_OVERRIDE:-}${WANT_MAGIC}" in
  0x5A5A0028|0x5A5A0013) CAP_CFLAG="-DMBXR_RT_CAP=4" ;;
  [1-4]*)                CAP_CFLAG="-DMBXR_RT_CAP=${MBXR_CAP_OVERRIDE}" ;;
  *)                     CAP_CFLAG="-DMBXR_RT_CAP=3" ;;
esac
SSH=(ssh -o BatchMode=yes -o StrictHostKeyChecking=no "$PYNQ_HOST")
RUN="$IISWC_OUT/$NAME"
if [ "$BOARD_ONLY" -eq 0 ]; then rm -rf "$RUN"; mkdir -p "$RUN"; fi
export PYTHONPATH="$ZCS${PYTHONPATH:+:$PYTHONPATH}"
export CPATH="$IISWC_ROOT/fpga/pynq-z2/sw${CPATH:+:$CPATH}"
export IISWC_ROOT
# Every child that imports the port needs this rung's window: the fidelity check sizes its
# output from me.T, hostrun builds against the generated C, and check_moonshine reads the IR.
export MOONSHINE_WINDOW_S="$WINDOW_S_OPT"
export MOONSHINE_DIR="${MOONSHINE_DIR:-$IISWC_OUT/moonshine}"
PY="$ZCS/tools/miniforge3/envs/zephyr/bin/python"; [ -x "$PY" ] || PY=python
NM=$(find "${ZEPHYR_SDK_INSTALL_DIR:-$ZCS/tools-manual}" -name 'riscv64-zephyr-elf-nm' 2>/dev/null | head -1)
OBJDUMP=$(find "${ZEPHYR_SDK_INSTALL_DIR:-$ZCS/tools-manual}" -name 'riscv64-zephyr-elf-objdump' 2>/dev/null | head -1)

vbase () { local b="${1%_perm}"; b="${b%_nhwc}"; b="${b%_smx2}"; b="${b%_smx}"; echo "$b"; }
vtarget () { case "$(vbase "$1")" in *_eng) echo roccmoon ;; *) echo "$TARGET" ;; esac; }
vkind () { local b; b="$(vbase "$1")"; echo "${b%_eng}"; }
vir () { case "${1%_perm}" in *_nhwc) echo "$RUN/enc/ir_nhwc" ;; *) echo "$RUN/enc/ir" ;; esac; }
# *_perm: the variant's curated tree plus permute4_s8 pext_block (patches/0107), which lives in
# kernels_t1 so that no other build picks it up.
vcurated () { case "$1" in *_smx2_perm|*_smx2_nhwc_perm) echo "$RUN/kernels_smx2_perm" ;;
  *_smx2|*_smx2_nhwc) echo "$RUN/kernels_smx2" ;; *_smx|*_smx_nhwc) echo "$RUN/kernels_smx" ;; *) echo "$KERNELS" ;; esac; }

MODELS=""
[ "$CONTROL" -eq 1 ] && MODELS="ctrl_ffn"
for V in $VARIANTS; do MODELS="$MODELS enc_$V"; done
if [ "$BIGCONV" -eq 1 ]; then case " $VARIANTS " in *" ew "*) MODELS="$MODELS enc_ew_bigconv" ;; esac; fi
if [ "$BIGCONV" -eq 1 ]; then case " $VARIANTS " in *" ew_smx "*) MODELS="$MODELS enc_ew_smx_bigconv" ;; esac; fi
if [ "$BIGCONV" -eq 1 ]; then case " $VARIANTS " in *" ew_smx2 "*) MODELS="$MODELS enc_ew_smx2_bigconv" ;; esac; fi
# The best software encoder with no engine in it: every measured software lever AND the conv
# kernel's buffers.  Without this the no-engine row is 4.3 G cycles of conv buffer limit
# (8.15.9's table), which is not what hart 0 can do.
if [ "$BIGCONV" -eq 1 ]; then case " $VARIANTS " in *" ew_smx2_nhwc_perm "*) MODELS="$MODELS enc_ew_smx2_nhwc_perm_bigconv" ;; esac; fi
for L in $STEMS; do MODELS="$MODELS stem_$L"; done
if [ "$BIGCONV" -eq 1 ]; then for L in $STEMS; do MODELS="$MODELS stem_${L}_bigconv"; done; fi
[ "$CONTROL" -eq 1 ] && MODELS="$MODELS ctrl_ffn_end"
[ -n "$ONLY_MODELS" ] && MODELS="$ONLY_MODELS"

if [ "$BOARD_ONLY" -eq 1 ]; then
  [ "$REPORT_ONLY" -eq 1 ] || for M in $MODELS; do need_file "$RUN/$M/zephyr.bin" "run --build-only first"; done
  info "--board-only: using the images in $RUN"
else
step "0/5  checkpoint, speech, and patches"
"$MOON/fetch_moonshine.sh" > "$RUN/fetch.log" 2>&1 || { cat "$RUN/fetch.log"; die "fetch_moonshine.sh failed"; }
# 0009 and 0060 exactly as scripts/39_rocket_xformer_cost.sh applies them (0060 edits lines
# 0009 added, so 0009 cannot be reverse-checked on its own once both are in).  0100 and 0102
# are checked both ways: each must either apply or be already applied, never half.
for P in 0009-modelblaster-pext-backend 0060-modelblaster-pext-pc-and-int-nonlin; do
  F="$IISWC_ROOT/patches/$P.patch"
  if git -C "$MB" apply --check "$F" >/dev/null 2>&1; then run git -C "$MB" apply "$F"; fi
done
# The later patches edit hunks inside earlier ones (0105 inside 0100's groupnorm_s8), so an
# earlier patch no longer reverse-applies on its own once a later one is in.  Check the stack
# from the top: if the LAST one reverse-applies, the stack below it is in (scripts/02 proves
# the whole stack reconstructs); otherwise apply each in order.
MB_STACK="0100-modelblaster-moonshine-ops 0102-modelblaster-roccmoon-backend 0103-modelblaster-q16-lowering 0104-modelblaster-softmax-memo 0105-modelblaster-moonshine-stem-nhwc 0106-modelblaster-softmax-memo2 0107-modelblaster-permute-block"
MB_TOP="$IISWC_ROOT/patches/${MB_STACK##* }.patch"
if git -C "$MB" apply --reverse --check "$MB_TOP" >/dev/null 2>&1; then
  info "patch stack through ${MB_STACK##* } already applied"
else
  for P in $MB_STACK; do
    F="$IISWC_ROOT/patches/$P.patch"
    if git -C "$MB" apply --check "$F" >/dev/null 2>&1; then run git -C "$MB" apply "$F"
    elif git -C "$MB" apply --reverse --check "$F" >/dev/null 2>&1; then info "$P already applied"
    else die "patches/$P neither applies nor is already applied to $MB"; fi
  done
fi

step "1/5  codegen  (encoder: $VARIANTS; stems: ${STEMS:-none}; control: $CONTROL)"
extract () {  # model out_dir fusion_target ncal [env...]
  local model="$1" out="$2" ft="$3" ncal="$4"; shift 4
  ( cd "$ZCS" && env "$@" "$PY" -m modelblaster.pipeline.extract_graph \
      --model "$model" --out-dir "$out" --quant int8 --num-calibration "$ncal" \
      --fusion-target "$ft" ) >> "$RUN/codegen.log" 2>&1 || { tail -30 "$RUN/codegen.log"; die "extract_graph ($model) failed"; }
}
MOON_ENV=(MB_INT8_GELU_AWARE_RANGES=1 MB_INT8_GOLDEN_C_FLOAT=1 MOONSHINE_WINDOW_S="$WINDOW_S_OPT")
codegen () {  # ir_dir gen_dir kind(ref|nl|ew) target [curated_dir]
  local ir="$1" gen="$2" kind="$3" tgt="$4" cur="${5:-$KERNELS}" extra=()
  mkdir -p "$gen"
  ( cd "$ZCS" && "$PY" -m modelblaster.pipeline.generate_skeleton \
      --ir "$ir/graph.json" --weights "$ir/weights.npz" --io "$ir/io.npz" \
      --out-dir "$gen" --backend "$tgt" ) >> "$RUN/codegen.log" 2>&1 || die "generate_skeleton failed ($gen)"
  case "$kind" in
    ref) ;;
    nl)  extra=(--global-curated-dir "$cur" --keep-reference-ops tanh_s8,groupnorm_s8,rope_s8,add_s8,mul_s8) ;;
    ew)  extra=(--global-curated-dir "$cur") ;;
  esac
  ( cd "$ZCS" && "$PY" -m modelblaster.pipeline.generate_kernels \
      --ir "$ir/graph.json" --out-dir "$gen" --backend reference --target "$tgt" \
      --quant int8 --io "$ir/io.npz" --repo-root "$MB" --build-dir "$gen.kverify" \
      --harness-dir "$MB/harness" --cache-dir "$gen.cache" --algorithms all "${extra[@]}" ) \
      >> "$RUN/codegen.log" 2>&1 || { tail -20 "$RUN/codegen.log"; die "generate_kernels failed ($gen)"; }
  need_file "$gen/kernels.c" "codegen produced no kernels ($gen)"
  cp "$gen/test_golden.bin" "$gen/test_golden_python.bin"
}
extract moonshine_enc "$RUN/enc/ir" "$TARGET" "$NCAL" "${MOON_ENV[@]}" MB_INT8_DUMP_ACTIVATIONS="$RUN/enc/ir/acts.npz"
case " $VARIANTS " in
  *_eng*)
    # The IR is target-independent except for extended fusion, which fires on no target
    # (extract_graph._FUSION_SAFE_TARGETS is empty).  Checked, not assumed.
    extract moonshine_enc "$RUN/enc/ir_roccmoon" roccmoon "$NCAL" "${MOON_ENV[@]}"
    for f in graph.json io.npz weights.npz; do
      cmp -s "$RUN/enc/ir/$f" "$RUN/enc/ir_roccmoon/$f" || die "extract_graph --fusion-target roccmoon changed $f"
    done
    info "IR identical for --fusion-target $TARGET and roccmoon (graph.json, io.npz, weights.npz)" ;;
esac
codegen "$RUN/enc/ir" "$RUN/enc/gen_ref" ref "$TARGET"
case " $VARIANTS " in
  *_smx*)
    rm -rf "$RUN/kernels_smx" "$RUN/kernels_smx2"; cp -r "$KERNELS" "$RUN/kernels_smx"
    rm -f "$RUN/kernels_smx/pext_nl/pext_nl_softmax_s8_pext_int_row.c"
    need_file "$RUN/kernels_smx/pext_nl/pext_nl_softmax_s8_pext_int_memo.c" "no pext_int_memo kernel"
    cp -r "$RUN/kernels_smx" "$RUN/kernels_smx2"
    rm -f "$RUN/kernels_smx2/pext_nl/pext_nl_softmax_s8_pext_int_memo.c"
    need_file "$RUN/kernels_smx2/pext_nl/pext_nl_softmax_s8_pext_int_memo2.c" "no pext_int_memo2 kernel"
    case " $VARIANTS " in
      *_perm*)
        rm -rf "$RUN/kernels_smx2_perm"; cp -r "$RUN/kernels_smx2" "$RUN/kernels_smx2_perm"
        cp "$IISWC_ROOT/fpga/pynq-z2/modelblaster/kernels_t1/pext_nl/pext_nl_permute4_s8_pext_block.c" \
           "$RUN/kernels_smx2_perm/pext_nl/" ;;
    esac ;;
esac
case " $VARIANTS " in
  *_nhwc*)
    mkdir -p "$RUN/enc/ir_nhwc"
    cp "$RUN/enc/ir/weights.npz" "$RUN/enc/ir/io.npz" "$RUN/enc/ir_nhwc/"
    ( cd "$ZCS" && "$PY" -m modelblaster.pipeline.assign_layouts "$RUN/enc/ir/graph.json" \
        "$RUN/enc/ir_nhwc/graph.json" --hint "$MOON/layout_hints_moonshine.json" --model moonshine_enc ) \
      >> "$RUN/codegen.log" 2>&1 || { tail -20 "$RUN/codegen.log"; die "assign_layouts failed"; }
    grep "policy=islands" "$RUN/codegen.log" | tail -1 | sed 's/^/    /' ;;
esac
for V in $VARIANTS; do codegen "$(vir "$V")" "$RUN/enc_$V/gen" "$(vkind "$V")" "$(vtarget "$V")" "$(vcurated "$V")"; done
for L in $STEMS; do
  extract "moonshine_stem_$L" "$RUN/stem_$L/ir" "$TARGET" "$NCAL" "${MOON_ENV[@]}"
  codegen "$RUN/stem_$L/ir" "$RUN/stem_$L/gen" ew "$TARGET"
done
if [ "$CONTROL" -eq 1 ]; then
  # Lab B19's own extraction of ffn_block (one calibration sample), at pext_nl.
  extract ffn_block "$RUN/ctrl_ffn/ir" "$TARGET" 1
  codegen "$RUN/ctrl_ffn/ir" "$RUN/ctrl_ffn/gen" ew "$TARGET"
fi
# THE RUNG'S OWN T, and the gate that the IR really has it.  The port derives T from the window;
# this asks the port, then checks the extracted graph agrees -- a rung whose IR was built at the
# wrong window would otherwise be measured as if it were 4 s and read a flattering RTF.
FRAMES=$( cd "$MOON" && MOONSHINE_WINDOW_S="$WINDOW_S_OPT" "$PY" -c "import moonshine_enc as me; print(me.T)" )
[ -n "$FRAMES" ] || die "could not derive the frame count for a ${WINDOW_S_OPT} s window"
"$PY" - "$RUN/enc/ir/graph.json" "$FRAMES" "$WINDOW_S_OPT" <<'PYT' || die "the extracted IR is not a ${WINDOW_S_OPT} s window"
import json, sys
g = json.load(open(sys.argv[1])); T = int(sys.argv[2])
# graph.json: "ops" carries the shapes, "dispatches" is a list of indices into it.
ms = sorted({o["shape"]["M"] for o in g["ops"]
             if o.get("op") in ("linear_s8", "linear_s8_pc") and "M" in o.get("shape", {})})
if not ms:
    sys.exit("no linear dispatches in the IR")
if max(ms) != T:
    sys.exit("the IR's longest linear is M = %d, but a %s s window is T = %d" % (max(ms), sys.argv[3], T))
print("    window %s s -> T = %d frames; the IR's linear dispatches are M in %s" % (sys.argv[3], T, ms))
PYT
"$PY" - "$RUN" <<'PY'
import json, os, sys, collections, glob
run = sys.argv[1]
g = json.load(open(os.path.join(run, "enc/ir/graph.json")))
c = collections.Counter(o["op"] for o in g["ops"])
print("    encoder IR: %d ops, %d dispatches: %s" % (len(g["ops"]), len(g["dispatches"]), dict(c)))
for p in sorted(glob.glob(os.path.join(run, "*/gen/kernel_picks.json"))):
    d = p.split(os.sep)[-3]
    picks = json.load(open(p))["picks"]
    print("    %-9s picks: %s" % (d, {k: (v.get("algorithm") or v["source"]) for k, v in picks.items()}))
PY

step "2/5  host gates (no board)"
GATE_ARGS=()
for V in $VARIANTS; do case "$V" in *_nhwc|*_perm) ;; *) GATE_ARGS+=(--variant "$V:$RUN/enc_$V/gen") ;; esac; done
STRESS=(); [ "$HOST_GATES" -eq 1 ] || STRESS=(--skip-stress)
( cd "$MOON" && "$PY" check_moonshine.py --ir "$RUN/enc/ir" --acts "$RUN/enc/ir/acts.npz" \
