import json, sys
a = json.load(open(sys.argv[1]))['picks']; b = json.load(open(sys.argv[2]))['picks']
alg = lambda v: v.get('algorithm') or v['source']
assert alg(a['permute4_s8']) == 'pext_block', ('permute4_s8 pick', alg(a['permute4_s8']))
diff = {k: (alg(b[k]), alg(a[k])) for k in a if k != 'permute4_s8' and alg(a[k]) != alg(b.get(k, {'source': None}))}
assert not diff, ('other picks changed', diff)
