"$PY" - "$RUN" "$GATE_VARIANTS" <<'PY' || die "a host gate FAILED -- see $RUN/host_gates.log"
import json, os, sys
run, variants = sys.argv[1], sys.argv[2].split()
h = json.load(open(os.path.join(run, "host_gates.json")))
bad = []
if not h["a_reference_vs_golden"]["every_dispatch_bit_exact"]:
    bad.append("(a) reference C != Python golden")
exact = {"tanh_s8", "add_s8", "rope_s8", "matmul_b_s8"}
for op, p in h["b3_model_data"]["per_kind"].items():
    if op in exact and p["mismatches"]:
        bad.append(f"(b3) {op} claimed bit_exact, {p['mismatches']} mismatches on model data")
for label in ("full", "san"):
    st = h.get(f"b2_stress_{label}")
    if st is None:
        continue
    for r in st["rows"]:
        if r["test"] != "groupnorm_s8_random" and r["mismatches"]:
            bad.append(f"(b2 {label}) {r['test']}: {r['mismatches']} mismatches")
    if st["returncode"]:
        bad.append(f"(b2 {label}) stress exited {st['returncode']}")
if h.get("b3_model_data_asan_ubsan", {}).get("returncode", 0):
    bad.append("(b3) ASan/UBSan model-data run failed")
for o in h.get("objects", []):
    if o.get("op") in ("add_s8", "mul_s8", "rope_s8", "matmul_b_s8", "groupnorm_s8") and \
            (o.get("softfloat_relocs") or o.get("libm_relocs")):
        bad.append(f"objects: {o['op']} links float: {o}")
eng = {}
for v in variants:
    if f"b4_model_{v}" not in h:
        bad.append(f"(b4) no whole-model run for {v}")
    if v.endswith("_eng"):
        twin = v[:-4]
        a = open(os.path.join(run, "host", f"host_c_golden_{v}.bin"), "rb").read()
        b = open(os.path.join(run, "host", f"host_c_golden_{twin}.bin"), "rb").read() \
            if os.path.exists(os.path.join(run, "host", f"host_c_golden_{twin}.bin")) else None
        picks = json.load(open(os.path.join(run, f"enc_{v}", "gen", "kernel_picks.json")))["picks"]
        pk = {k: picks.get(k, {}).get("algorithm") for k in ("linear_s8", "conv2d_s8")}
        eng[v] = {"twin": twin, "host_c_golden_identical_to_twin": (a == b) if b is not None else None,
                  "picks": pk}
        if b is None:
            bad.append(f"(eng) {v}: twin {twin} not in this run, golden identity unchecked")
        elif a != b:
            bad.append(f"(eng) {v}: host-C golden differs from {twin}'s")
        if any(x != "roccmoon_engine" for x in pk.values()):
            bad.append(f"(eng) {v}: picks {pk}, expected roccmoon_engine")
smx = {}
for v in variants:
    if v.endswith("_smx") or v.endswith("_smx2"):
        twin = v[:v.rindex("_smx")]
        want = "pext_int_memo2" if v.endswith("_smx2") else "pext_int_memo"
        pa = os.path.join(run, "host", f"host_c_golden_{v}.bin")
        pb = os.path.join(run, "host", f"host_c_golden_{twin}.bin")
        a = open(pa, "rb").read()
        b = open(pb, "rb").read() if os.path.exists(pb) else None
        pick = json.load(open(os.path.join(run, f"enc_{v}", "gen", "kernel_picks.json")))["picks"].get("softmax_s8", {}).get("algorithm")
        smx[v] = {"twin": twin, "host_c_golden_identical_to_twin": (a == b) if b is not None else None, "softmax_pick": pick}
        if b is None:
            bad.append(f"(smx) {v}: twin {twin} not in this run, golden identity unchecked")
        elif a != b:
            bad.append(f"(smx) {v}: host-C golden differs from {twin}'s -- {want} must be bit-exact")
        if pick != want:
            bad.append(f"(smx) {v}: softmax pick {pick}, expected {want}")
if smx:
    h["softmax_memo_variants"] = smx
    json.dump(h, open(os.path.join(run, "host_gates.json"), "w"), indent=1, default=str)
    for v, e in smx.items():
        print(f"    {v}: host-C golden identical to {e['twin']}'s: {e['host_c_golden_identical_to_twin']}; softmax {e['softmax_pick']}")
if eng:
    h["engine_variants"] = eng
    json.dump(h, open(os.path.join(run, "host_gates.json"), "w"), indent=1, default=str)
print("    host gates:", "PASS" if not bad else "FAIL: " + "; ".join(bad))
for v, e in eng.items():
    print(f"    {v}: host-C golden identical to {e['twin']}'s: {e['host_c_golden_identical_to_twin']}; picks {e['picks']}")
