"$PY" - "$RUN" "$MODELS" <<'PY' | tee "$RUN/report.txt"
import hashlib, json, os, re, sys
run, models = sys.argv[1], sys.argv[2].split()
CLK = 34482759.0
WINDOW_S = float(os.environ.get("MB_WINDOW_S", "4.0"))
FRAMES = int(os.environ.get("MB_FRAMES", "165"))


def work(op, s):
    """(MACs, output elements) of one dispatch, from its IR shape."""
    if op in ("linear_s8", "linear_s8_pc"):
        return s["M"] * s["K"] * s["N"], s["M"] * s["N"]
    if op in ("conv2d_s8", "conv2d_s8_pc"):
        return (s["OC"] * s["OH"] * s["OW"] * s["IC"] * s["KH"] * s["KW"],
                s["N"] * s["OC"] * s["OH"] * s["OW"])
    if op == "matmul_b_s8":
        return s["B"] * s["M"] * s["K"] * s["N"], s["B"] * s["M"] * s["N"]
    if op == "permute4_s8":
        return 0, s["d0"] * s["d1"] * s["d2"] * s["d3"]
    if op == "groupnorm_s8":
        return 0, s["N"] * s["C"] * s["H"] * s["W"]
    if op == "rope_s8":
        return 0, s["T"] * s["H"] * s["D"]
    if "n" in s:
        return 0, s["n"]
    if "M" in s and "K" in s:
        return 0, s["M"] * s["K"]
    return 0, 0


def rd(d, f):
    p = os.path.join(d, f)
    return open(p).read().strip() if os.path.exists(p) else None


def model(name):
    d = os.path.join(run, name)
    irp = os.path.join(d, "ir", "graph.json") if os.path.exists(os.path.join(d, "ir", "graph.json")) \
        else os.path.join(run, "enc", "ir", "graph.json")
    g = json.load(open(irp))
    picks = json.load(open(os.path.join(d, "gen", "kernel_picks.json")))["picks"]
    txt = open(os.path.join(d, "console.txt"), errors="replace").read() if os.path.exists(
        os.path.join(d, "console.txt")) else ""
    runl = next((l for l in txt.splitlines() if l.startswith("MB_PEXT_RUN ")), None)
    peeks = [json.loads(l) for l in open(os.path.join(d, "peeks.jsonl"))] if os.path.exists(
        os.path.join(d, "peeks.jsonl")) else []
    img_p = os.path.join(d, "zephyr.bin")
    # TIE THE ARTEFACT TO THE MEASUREMENT BY CHECKSUM.  The bitstream's md5 is already in every
    # row; the IMAGE's was only ever in a sidecar file, so a run.json could not say which bytes
    # produced its cycles.  Now it can, and an A/B whose two images differ by more than the one
    # flag it claims is detectable from the record alone.
    res = {"image_bytes": os.path.getsize(img_p) if os.path.exists(img_p) else None,
           "image_md5": (hashlib.md5(open(img_p, "rb").read()).hexdigest()
                         if os.path.exists(img_p) else None),
           "ran": runl is not None, "target": rd(d, "target.txt"), "warmup": rd(d, "warmup.txt"),
           "kernel_picks": {k: (v.get("algorithm") or v["source"]) for k, v in picks.items()},
           "kernel_cflags": rd(d, "kernel_cflags.txt"), "bitstream_md5": rd(d, "bitstream_md5.txt"),
           "fclk_as_run": json.load(open(os.path.join(d, "fclk.json"))) if rd(d, "fclk.json") else None,
           "console_bytes": len(txt), "ram_reads": peeks,
           "board_side": rd(d, "board_side.log")}
    if runl is None:
        res["banner_seen"] = "Booting Zephyr" in txt
        res["main_seen"] = "MB_PEXT_BUILD" in txt
        return res
    kv = {k: int(v) for k, v in re.findall(r"(\w+)=(-?\d+)", runl)}
    res.update({k: kv.get(k) for k in ("cpu", "mhartid", "median", "min", "max", "warm", "max_abs_err")})
    res["result_line"] = next((l for l in txt.splitlines() if l.startswith("RESULT:")), None)
    eng = {}
    for l in txt.splitlines():
        if l.startswith("MB_ROCCMOON "):
            e = dict(re.findall(r"(\w+)=(\S+)", l))
            ph = e.pop("phase")   # pop BEFORE the comprehension: `d[e.pop()] = {..e..}` runs the RHS first
            eng[ph] = {k: (int(v, 0) if re.fullmatch(r"-?(0x[0-9a-fA-F]+|\d+)", v) else v) for k, v in e.items()}
    if eng:
        if "warm" in eng and "total" in eng:
            eng["timed"] = {k: eng["total"][k] - eng["warm"][k] for k in eng["total"]
                            if k not in ("last_rc", "last_status") and isinstance(eng["total"][k], int)
                            and isinstance(eng["warm"].get(k), int)}
        res["roccmoon_stats"] = eng
    for l in txt.splitlines():
        if l.startswith("MB_SMX2 "):
            e = dict(re.findall(r"(\w+)=(\S+)", l))
            hist = {}
            for kv_ in e.pop("d0_hist", "").split(","):
                if ":" in kv_:
                    a_, b_ = kv_.split(":")
                    hist[int(a_)] = int(b_)
            res["smx2_stats"] = {k: int(v) for k, v in e.items() if re.fullmatch(r"\d+", v)}
            res["smx2_stats"]["d0_hist"] = hist
    ops = {}
    for l in txt.splitlines():
        if l.startswith("MB_PEXT_OP "):
            o = dict(re.findall(r"(\w+)=(\S+)", l))
            ops[o["name"]] = int(o["cycles"])
    rows, kinds = [], {}
    for o in g["ops"]:
        if o.get("dispatch_id") is None or o["name"] not in ops:
            continue
        macs, els = work(o["op"], o["shape"])
        cyc = ops[o["name"]]
        rows.append({"dispatch": o["dispatch_id"], "name": o["name"], "op": o["op"],
                     "shape": o["shape"], "cycles": cyc, "macs": macs, "elements": els,
                     "kernel": res["kernel_picks"].get(o["op"])})
        k = kinds.setdefault(o["op"], {"dispatches": 0, "cycles": 0, "macs": 0, "elements": 0,
                                        "kernel": res["kernel_picks"].get(o["op"])})
        k["dispatches"] += 1
        k["cycles"] += cyc
        k["macs"] += macs
        k["elements"] += els
    tot = sum(r["cycles"] for r in rows)
    for k in kinds.values():
        k["share_pct"] = round(100.0 * k["cycles"] / tot, 3) if tot else None
        k["cycles_per_mac"] = round(k["cycles"] / k["macs"], 4) if k["macs"] else None
        k["cycles_per_element"] = round(k["cycles"] / k["elements"], 3) if k["elements"] else None
        k["seconds"] = round(k["cycles"] / CLK, 3)
    res.update({"dispatch_cycles_total": tot, "seconds": tot / CLK, "rows": rows, "per_kind": kinds,
                "dispatches_profiled": len(rows), "dispatches_in_ir": len(g["dispatches"])})
    if name.startswith("enc"):
        res["rtf_4s"] = tot / CLK / WINDOW_S
        # THE HEADLINE NUMBER, IN THE RECORD AND NOT ONLY IN PROSE.  Every engine RTF this project
        # quotes is steady state: the dispatch total less the ONE-TIME weight-image build, which is
        # paid once per model load and not once per utterance.  It used to be derivable from
        # per-model fields but was written down nowhere, so run.json now carries it for every image
        # -- image_cycles is 0 for a software one, and then steady == the dispatch total.
        img_c = ((res.get("roccmoon_stats", {}).get("timed")
                  or res.get("roccmoon_stats", {}).get("total") or {}).get("image_cycles", 0))
        res["image_cycles_once"] = img_c
        res["steady_cycles"] = tot - img_c
        res["rtf_steady"] = (tot - img_c) / CLK / WINDOW_S
    return res


out = {"lab": "B26 moonshine_enc",
       "model": "UsefulSensors/moonshine-tiny@390624ed33d594443aa4aa221f5b9f283b545b5a encoder",
       "window_s": WINDOW_S, "encoder_frames": FRAMES, "clock_hz": CLK, "hart": 0,
       "bitstream_md5": os.environ.get("BIT_MD5") or next(
           (rd(os.path.join(run, m), "bitstream_md5.txt") for m in models
            if rd(os.path.join(run, m), "bitstream_md5.txt")), "unknown"),   # --report-only "bitstream_note": os.environ.get("BIT_NOTE", ""),
       "soc_magic": os.environ.get("WANT_MAGIC", ""),
       "fclk": json.load(open(os.path.join(run, "fclk.json"))) if os.path.exists(os.path.join(run, "fclk.json")) else None,
       "clocks": json.load(open(os.path.join(run, "clocks.json"))) if os.path.exists(os.path.join(run, "clocks.json")) else None,
       "models": {}}
for m in models:
    if os.path.isdir(os.path.join(run, m)):
        out["models"][m] = model(m)

for m, r in out["models"].items():
    if not r.get("ran"):
        last = r["ram_reads"][-1] if r["ram_reads"] else {}
        print(f"\n-- {m}: NO RESULT (console {r['console_bytes']} bytes, banner {r.get('banner_seen')}, "
              f"main {r.get('main_seen')}); RAM at the end: {json.dumps({k: v for k, v in last.items() if k != 'records_'})[:300]}")
        continue
    head = f"\n-- {m}  {r['dispatch_cycles_total']:,} cycles = {r['seconds']:.2f} s"
    if "rtf_4s" in r:
        head += f" for {WINDOW_S} s of audio, RTF {r['rtf_4s']:.2f}"
        if r.get("image_cycles_once"):
            head += f"; steady {r['steady_cycles']:,} = RTF {r['rtf_steady']:.3f} (image {r['image_cycles_once']:,})"
    print(head + f"   (run {r['median']:,}, warm {r['warm']:,}, max_abs_err {r['max_abs_err']} vs its host-C golden)")
    print("   %-13s %4s %14s %7s %14s %12s %10s %11s  %s" % ("op", "n", "cycles", "share", "MACs",
          "elements", "cyc/MAC", "cyc/elem", "kernel"))
    for op, k in sorted(r["per_kind"].items(), key=lambda kv: -kv[1]["cycles"]):
        print("   %-13s %4d %14s %6.2f%% %14s %12s %10s %11s  %s" % (
            op, k["dispatches"], f"{k['cycles']:,}", k["share_pct"], f"{k['macs']:,}" if k["macs"] else "-",
            f"{k['elements']:,}", k["cycles_per_mac"] or "-", k["cycles_per_element"], k["kernel"]))
    if r.get("roccmoon_stats"):
        print("   engine stats (timed = total - warm):", json.dumps(r["roccmoon_stats"].get("timed", r["roccmoon_stats"]))[:400])
    if m.startswith("stem"):
        for row in r["rows"]:
            sh = row["shape"]
            if row["op"] == "conv2d_s8":
                print("     %-12s KH=%s KW=%s SH=%s SW=%s  %14s cycles  %.3f cyc/MAC" % (
                    row["name"], sh["KH"], sh["KW"], sh["SH"], sh["SW"], f"{row['cycles']:,}", row["cycles"] / row["macs"]))

M = out["models"]
for sfx in ("", "_bigconv"):
    w, h = M.get("stem_w" + sfx, {}), M.get("stem_h" + sfx, {})
    if not (w.get("ran") and h.get("ran")):
        continue
    wr = {r["name"]: r for r in w["rows"]}
    hr = {r["name"]: r for r in h["rows"]}
    lever = {}
    print("\n-- the layout lever on Moonshine's stem%s: time on H / time on W, per dispatch" % sfx)
    for n in wr:
        if n in hr:
            lever[n] = {"op": wr[n]["op"], "w_cycles": wr[n]["cycles"], "h_cycles": hr[n]["cycles"],
                        "h_over_w": round(hr[n]["cycles"] / wr[n]["cycles"], 3),
                        "w_cyc_per_mac": round(wr[n]["cycles"] / wr[n]["macs"], 4) if wr[n]["macs"] else None,
                        "h_cyc_per_mac": round(hr[n]["cycles"] / hr[n]["macs"], 4) if hr[n]["macs"] else None}
            print("   %-16s %-12s W %14s  H %14s  H/W %.3f" % (n, wr[n]["op"], f"{wr[n]['cycles']:,}",
                  f"{hr[n]['cycles']:,}", lever[n]["h_over_w"]))
    out["stem_layout_lever" + sfx] = lever
# The engine against its twins.  Two twins where the lab built both: the same generated C
# (enc_ew: pext_patch_dot8 at its default limits, which sends conv3 to the scalar reference)
# and enc_ew_bigconv (the same C with the conv kernel's limits raised, conv3 on DOT8 -- the fair
# MBP baseline for conv2d_s8).  The encoder images run no warm-up, so the engine's ONE-TIME
# weight-image build (mbxr_rt_stats.image_cycles, spent inside the first call of each layer) is
# inside its measured dispatches; "excl_image" subtracts that measured counter.
for v in list(M):
    if not (v.startswith("enc_") and v.endswith("_eng") and M[v].get("ran")):
        continue
    img = (M[v].get("roccmoon_stats", {}).get("timed") or M[v].get("roccmoon_stats", {}).get("total") or {}).get("image_cycles", 0)
    for tw in (v[:-4], v[:-4] + "_bigconv"):
        t = M.get(tw, {})
        if not t.get("ran"):
            continue
        cmp = {op: {"engine_cycles": M[v]["per_kind"][op]["cycles"], "twin_cycles": t["per_kind"][op]["cycles"],
                    "speedup": round(t["per_kind"][op]["cycles"] / M[v]["per_kind"][op]["cycles"], 3)}
               for op in ("linear_s8", "conv2d_s8") if op in M[v]["per_kind"] and op in t["per_kind"]}
        eng_ll = sum(M[v]["per_kind"][op]["cycles"] for op in ("linear_s8", "conv2d_s8") if op in M[v]["per_kind"])
        tw_ll = sum(t["per_kind"][op]["cycles"] for op in ("linear_s8", "conv2d_s8") if op in t["per_kind"])
        cmp["linear_plus_conv_excl_image"] = {"engine_cycles": eng_ll - img, "twin_cycles": tw_ll,
                                              "speedup": round(tw_ll / (eng_ll - img), 3)}
        cmp["total"] = {"engine_cycles": M[v]["dispatch_cycles_total"], "twin_cycles": t["dispatch_cycles_total"],
                        "speedup": round(t["dispatch_cycles_total"] / M[v]["dispatch_cycles_total"], 3)}
        cmp["total_excl_image"] = {"engine_cycles": M[v]["dispatch_cycles_total"] - img,
                                   "twin_cycles": t["dispatch_cycles_total"], "image_cycles": img,
                                   "speedup": round(t["dispatch_cycles_total"] / (M[v]["dispatch_cycles_total"] - img), 3),
                                   "rtf_4s_engine": round((M[v]["dispatch_cycles_total"] - img) / CLK / WINDOW_S, 3)}
        out.setdefault("engine_vs_twin", {})[f"{v}_vs_{tw}"] = cmp
        print(f"\n-- {v} against {tw}: {json.dumps(cmp)}")
json.dump(out, open(os.path.join(run, "run.json"), "w"), indent=1)
print(f"\nwrote {os.path.join(run, 'run.json')}")
